    @Override public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
    private Class<?> type(String n)throws Exception{return Class.forName("org.simpleweather.app."+n,true,loader);}
    private Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
    private Object call(Object o,String n,Class<?>[] t,Object...v)throws Exception{Method m=(o instanceof Class?(Class<?>)o:o.getClass()).getDeclaredMethod(n,t);m.setAccessible(true);return m.invoke(o instanceof Class?null:o,v);}
    private void ui(Runnable r){AtomicReference<Throwable> e=new AtomicReference<>();runOnMainSync(()->{try{r.run();}catch(Throwable t){e.set(t);}});if(e.get()!=null)throw new RuntimeException(e.get());waitForIdleSync();}
    private void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}
    private void collect(View v,List<String> out){if(v instanceof TextView)out.add(((TextView)v).getText().toString());if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)collect(((ViewGroup)v).getChildAt(i),out);}
    private List<String> texts(Activity a){List<String> out=new ArrayList<>();collect(a.getWindow().getDecorView(),out);return out;}
    private void install(String id)throws Exception{try(InputStream in=new FileInputStream("/data/local/tmp/internal-apps/"+id+".ddapp")){call(apps,"install",new Class[]{InputStream.class,String.class,String.class},in,id,null);}}
    private Activity open(String id)throws Exception{Intent intent=(Intent)type("ModuleRuntime").getMethod("pageIntent",Context.class,String.class,String.class).invoke(null,host,id,"main");Activity a=startActivitySync(intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();return a;}
    private void await(java.util.function.BooleanSupplier condition,String label)throws Exception{long end=SystemClock.elapsedRealtime()+10000;while(!condition.getAsBoolean()&&SystemClock.elapsedRealtime()<end)Thread.sleep(50);check(condition.getAsBoolean(),label);}
    @Override public void onStart(){Bundle result=new Bundle();try{
        c=getTargetContext();loader=c.getClassLoader();String lang=args.getString("language","zh-CN");c.getSharedPreferences("toolbox",0).edit().putString("app_language",lang).putInt("seen_version",54).commit();
        host=startActivitySync(new Intent().setClassName(c,"org.simpleweather.app.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();apps=field(host,"apps");
        for(String id:new String[]{"weather","schedule","status","weather-map","astronomy","earthquake","random","todo","music","messaging","colorvision"}){install(id);check((Boolean)call(apps,"installed",new Class[]{String.class},id),"installed "+id);File file=new File(c.getFilesDir(),"apps/"+id+".ddapp");check((android.system.Os.stat(file.getPath()).st_mode&0222)==0,"read-only "+id);}
        for(String n:new String[]{"org.daidai.modules.music.MusicActivity","org.daidai.modules.messaging.MessagingService","org.daidai.modules.colorvision.ColorVisionActivity","org.simpleweather.app.WeatherScreen"}){try{Class.forName(n,true,loader);throw new AssertionError("business bundled in host: "+n);}catch(ClassNotFoundException expected){checks++;}}
        for(String id:new String[]{"music","messaging","colorvision"}){child=open(id);Object page=field(child,"page");check(page!=null,"page opened "+id);check(page.getClass().getClassLoader()!=loader,"separate classloader "+id);check(texts(child).size()>8,"real resource-backed UI "+id);String expected=lang.equals("en")?(id.equals("music")?"Playback":id.equals("messaging")?"Device Messaging":"Color Vision Simulator"):(id.equals("music")?"播放":id.equals("messaging")?"设备通信":"色觉模拟器");check(texts(child).toString().contains(expected),"localized UI "+id+" "+texts(child));ui(()->child.finish());child=null;}
        child=open("music");Class<?> collections=Class.forName("org.daidai.modules.music.MusicCollections",true,field(child,"page").getClass().getClassLoader());check((Boolean)call(collections,"createPlaylist",new Class[]{Context.class,String.class},child,"Resource context check"),"playlist uses module resources across locales");call(collections,"deletePlaylist",new Class[]{Context.class,String.class},child,"Resource context check");check(!(Boolean)call(collections,"createPlaylist",new Class[]{Context.class,String.class},child,"All songs"),"English reserved playlist name remains protected");check(!(Boolean)call(collections,"createPlaylist",new Class[]{Context.class,String.class},child,"全部歌曲"),"Chinese reserved playlist name remains protected");ui(()->child.finish());child=null;
        packages();backup();notifications();messaging();
        result.putString("result","PASS: "+checks+" internal app behavior checks ("+lang+")");
    }catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));result.putString("result","FAIL: "+s);}finally{if(child!=null)ui(()->child.finish());if(host!=null)ui(()->host.finish());finish(Activity.RESULT_OK,result);}}
    private void backup()throws Exception{
        SharedPreferences p=c.getSharedPreferences("music_module",0);p.edit().clear().putString("catalogue","[]").putString("queue","[]").putString("collections","{}").putInt("volume_percent",17).commit();File data=(File)type("ModuleRuntime").getMethod("dataDirectory",Context.class,String.class).invoke(null,c,"music");File sample=new File(data,"test-backup.txt");Files.write(sample.toPath(),"archive-data".getBytes("UTF-8"));
        Map<String,Map<String,?>> groups=new LinkedHashMap<>();String[] names=(String[])fieldStatic(type("ConfigurationData"),"GROUPS");for(String n:names)groups.put(n,c.getSharedPreferences(n,0).getAll());JSONObject config=(JSONObject)call(type("ConfigurationData"),"encode",new Class[]{Map.class,byte[].class,byte[].class},groups,null,null);byte[] bytes=config.toString().getBytes("UTF-8");
        File archive=(File)call(type("InternalDataBackup"),"exportData",new Class[]{Context.class,byte[].class},c,bytes);check(archive.length()>0,"full data archive written");p.edit().putInt("volume_percent",88).commit();Files.write(sample.toPath(),"changed".getBytes("UTF-8"));Object prepared=call(type("InternalDataBackup"),"read",new Class[]{Context.class,Uri.class},c,Uri.fromFile(archive));call(prepared,"apply",new Class[]{Context.class},c);check((Boolean)call(prepared,"finish",new Class[]{Context.class,boolean.class},c,true),"archive commit");check(p.getInt("volume_percent",0)==17,"music settings restored");check(new String(Files.readAllBytes(sample.toPath()),"UTF-8").equals("archive-data"),"module file restored");
        p.edit().putInt("volume_percent",44).commit();Files.write(sample.toPath(),"before-rollback".getBytes("UTF-8"));Object rollback=call(type("InternalDataBackup"),"read",new Class[]{Context.class,Uri.class},c,Uri.fromFile(archive));call(rollback,"apply",new Class[]{Context.class},c);check((Boolean)call(rollback,"finish",new Class[]{Context.class,boolean.class},c,false),"archive rollback completes");check(p.getInt("volume_percent",0)==44&&new String(Files.readAllBytes(sample.toPath()),"UTF-8").equals("before-rollback"),"files and preferences rolled back together");
        for(String fault:new String[]{"wrong-type","wrong-version","checksum","traversal"}){File bad=new File(c.getCacheDir(),"invalid-"+fault+".zip");try(java.util.zip.ZipFile original=new java.util.zip.ZipFile(archive);java.util.zip.ZipOutputStream zip=new java.util.zip.ZipOutputStream(new FileOutputStream(bad))){java.util.Enumeration<? extends java.util.zip.ZipEntry> entries=original.entries();while(entries.hasMoreElements()){java.util.zip.ZipEntry entry=entries.nextElement();byte[] content;try(InputStream in=original.getInputStream(entry);ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1)b.write(buffer,0,n);content=b.toByteArray();}if(entry.getName().equals("internal.json")){JSONObject root=new JSONObject(new String(content,"UTF-8"));if(fault.equals("wrong-type"))root.getJSONArray("apps").getJSONObject(0).getJSONObject("preferences").put("volume_percent",new JSONObject().put("type","string").put("value","invalid"));if(fault.equals("wrong-version"))root.put("version",99);if(fault.equals("checksum"))root.getJSONArray("apps").getJSONObject(0).getJSONArray("files").getJSONObject(0).put("sha256","0000");content=root.toString().getBytes("UTF-8");}zip.putNextEntry(new java.util.zip.ZipEntry(entry.getName()));zip.write(content);zip.closeEntry();}if(fault.equals("traversal")){zip.putNextEntry(new java.util.zip.ZipEntry("../foreign"));zip.write(1);zip.closeEntry();}}boolean rejected=false;try{call(type("InternalDataBackup"),"read",new Class[]{Context.class,Uri.class},c,Uri.fromFile(bad));}catch(InvocationTargetException expected){rejected=true;}check(rejected,"reject malformed data "+fault);check(p.getInt("volume_percent",0)==44,"invalid file leaves data "+fault);bad.delete();}
        File old=new File(c.getCacheDir(),"legacy-config.json");Files.write(old.toPath(),bytes);Object legacy=call(type("InternalDataBackup"),"read",new Class[]{Context.class,Uri.class},c,Uri.fromFile(old));check(((List<?>)field(legacy,"parts")).isEmpty(),"legacy JSON does not replace internal data");call(legacy,"close",new Class[]{});old.delete();archive.delete();sample.delete();
    }
    private void packages()throws Exception{
        for(String id:new String[]{"music","messaging","colorvision"}){child=open(id);Object previous=field(child,"page");install(id);await(()->child.isFinishing()||child.isDestroyed(),"update closes old page "+id);child=open(id);check(field(child,"page").getClass().getClassLoader()!=previous.getClass().getClassLoader(),"update uses new executable "+id);try(ParcelFileDescriptor shot=getUiAutomation().executeShellCommand("screencap -p /data/local/tmp/internal-"+id+".png")){while(new FileInputStream(shot.getFileDescriptor()).read()!=-1){}}ui(()->child.finish());child=null;SharedPreferences p=c.getSharedPreferences(id+"_module",0);p.edit().putString("retention_sentinel","preserve").commit();ui(()->{try{call(apps,"uninstall",new Class[]{String.class},id);}catch(Exception e){throw new RuntimeException(e);}});await(()->{try{return !(Boolean)call(apps,"installed",new Class[]{String.class},id)&&!(Boolean)field(apps,"busy");}catch(Exception e){return false;}},"uninstall finishes "+id);check(p.getString("retention_sentinel","").equals("preserve"),"uninstall retains data "+id);p.edit().remove("retention_sentinel").commit();install(id);check((Boolean)call(apps,"installed",new Class[]{String.class},id),"reinstall "+id);}
        File original=new File(c.getFilesDir(),"apps/weather.ddapp");String digest=(String)call(type("AppModules"),"sha",new Class[]{File.class},original);for(String fault:new String[]{"corrupt","wrong-signer","wrong-api","zip-slip","metadata-only"}){boolean rejected=false;try(InputStream in=new FileInputStream("/data/local/tmp/module-host-test/"+fault+".ddapp")){call(apps,"install",new Class[]{InputStream.class,String.class,String.class},in,"weather",null);}catch(InvocationTargetException expected){rejected=true;}check(rejected,"reject invalid executable "+fault);check(digest.equals(call(type("AppModules"),"sha",new Class[]{File.class},original)),"invalid update retains original "+fault);}
    }
    private Object fieldStatic(Class<?> t,String n)throws Exception{Field f=t.getDeclaredField(n);f.setAccessible(true);return f.get(null);}
    private void notifications()throws Exception{
        Object model=type("ScheduleModel").getConstructor().newInstance();Class<?> course=type("ScheduleModel$Course");Object row=course.getConstructor().newInstance();java.time.LocalDate day=java.time.LocalDate.now();course.getField("day").setInt(row,day.getDayOfWeek().getValue());course.getField("name").set(row,"Countdown test");((List)type("ScheduleModel").getField("courses").get(model)).add(row);String raw=call(model,"json",new Class[]{}).toString();SharedPreferences p=c.getSharedPreferences("timetable",0);String before=p.getString("data","");p.edit().putString("data",raw).commit();c.getSharedPreferences("toolbox",0).edit().putBoolean("course_notify",true).commit();long start=day.atTime(8,0).atZone(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli();
        call(type("ScheduleNotifier"),"refreshAt",new Class[]{Context.class,long.class,boolean.class},c,start-20*60000,true);android.service.notification.StatusBarNotification found=null;for(android.service.notification.StatusBarNotification n:c.getSystemService(NotificationManager.class).getActiveNotifications())if("course".equals(n.getTag()))found=n;check(found!=null,"course reminder posted");Notification n=found.getNotification();check(n.when==start,"chronometer target is class start");check(n.extras.getBoolean(Notification.EXTRA_SHOW_CHRONOMETER),"system chronometer enabled");check(n.extras.getBoolean(Notification.EXTRA_CHRONOMETER_COUNT_DOWN),"system countdown enabled");call(type("ScheduleNotifier"),"refreshAt",new Class[]{Context.class,long.class,boolean.class},c,start+60000,true);for(android.service.notification.StatusBarNotification x:c.getSystemService(NotificationManager.class).getActiveNotifications())if("course".equals(x.getTag()))check(!x.getNotification().extras.getBoolean(Notification.EXTRA_SHOW_CHRONOMETER),"class start changes notification state");p.edit().putString("data",before).commit();call(type("ScheduleNotifier"),"refresh",new Class[]{Context.class,boolean.class},c,false);
    }
    private void messaging()throws Exception{
        child=open("messaging");Object page=field(child,"page");await(()->{try{return field(page,"session")!=null;}catch(Exception e){return false;}},"messaging bound");Object service=field(page,"session");ClassLoader cl=service.getClass().getClassLoader();Intent intent=(Intent)type("ModuleRuntime").getMethod("serviceIntent",Context.class,String.class).invoke(null,c,"messaging");ui(()->c.startForegroundService(intent.setAction("wait")));await(()->{try{return (Boolean)call(service,"active",new Class[]{});}catch(Exception e){return false;}},"background session active");String code=(String)call(service,"code",new Class[]{});Class<?> listener=Class.forName("org.daidai.modules.messaging.MessagePeer$Listener",true,cl);java.util.concurrent.CountDownLatch connected=new java.util.concurrent.CountDownLatch(1),reply=new java.util.concurrent.CountDownLatch(1);Object proxy=java.lang.reflect.Proxy.newProxyInstance(cl,new Class[]{listener},(o,m,v)->{if(m.getName().equals("state")&&"connected".equals(v[0]))connected.countDown();if(m.getName().equals("received")&&"reply".equals(v[0]))reply.countDown();return null;});Object peer=Class.forName("org.daidai.modules.messaging.LanPeer",true,cl).getConstructor(listener).newInstance(proxy);call(peer,"connect",new Class[]{String.class,String.class},"10.0.2.15",code);check(connected.await(10,java.util.concurrent.TimeUnit.SECONDS),"encrypted LAN handshake");ui(()->child.finish());child=null;c.startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();call(peer,"send",new Class[]{String.class},"background message");await(()->{try{return ((List<?>)call(service,"messages",new Class[]{})).size()>0;}catch(Exception e){return false;}},"message received after leaving page");ui(()->{try{call(service,"send",new Class[]{String.class},"reply");}catch(Exception e){throw new RuntimeException(e);}});check(reply.await(5,java.util.concurrent.TimeUnit.SECONDS),"background encrypted reply");try{shell("input keyevent 223");await(()->!c.getSystemService(PowerManager.class).isInteractive(),"emulator screen off");call(peer,"send",new Class[]{String.class},"screen-off message");await(()->{try{List<?> messages=(List<?>)call(service,"messages",new Class[]{});return !messages.isEmpty()&&"screen-off message".equals(messages.get(messages.size()-1).getClass().getField("text").get(messages.get(messages.size()-1)));}catch(Exception e){return false;}},"encrypted message received while screen off");}finally{shell("input keyevent 224");shell("wm dismiss-keyguard");}ui(()->{try{call(service,"disconnect",new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});check(field(service,"cpu")==null&&field(service,"wifi")==null,"connection locks released");call(peer,"close",new Class[]{});
    }
